INSERT OR IGNORE INTO blog_posts (slug, language, title, seo_title, excerpt, category, series, image, image_alt, published, published_iso, read_time, intro, sections, content_notice_label, content_notice_text, status, created_at) VALUES ('conto-o-bilhete-na-lista-de-compras', 'pt-BR', 'O bilhete na lista de compras', NULL, 'Um conto sobre um casal de longa data, uma lista de compras e o bilhete que lembrou os dois de que ainda sabem se surpreender.', 'CONTOS', 'CONTOS', '', 'Lista de compras presa na porta da geladeira com um ímã de abacaxi e um bilhete escrito à mão', '4 de outubro de 2026', '2026-10-04', '4 min de leitura', '[]', '[{"heading":"A lista na porta da geladeira","paragraphs":["Tereza escrevia a lista de compras toda sexta-feira, na mesma letra miúda, presa à porta da geladeira com o ímã de abacaxi. Arroz, café, sabão, banana. Em trinta e dois anos de casamento, Alberto aprendera a ler aquela lista como quem lê o tempo: sem drama, só para saber o que vinha pela frente.","Naquela sexta, porém, ele parou diante dela mais do que de costume. Entre o café e o sabão, na mesma letra miúda, havia uma linha nova: \"Uma tarde inteira com você.\"","Alberto riu sozinho, depois ficou sério. Olhou para o corredor. Tereza mexia numa planta na varanda, de costas, fingindo não esperar nada."]},{"heading":"Resposta em letra torta","paragraphs":["Ele pegou a caneta pendurada num barbante e, embaixo da linha dela, escreveu com a letra torta de quem nunca teve pressa: \"Marcado. Eu levo o pão.\"","Não disseram nada durante o jantar. Falaram do vizinho, da torneira que pingava, do neto que ligou pedindo dinheiro emprestado. Mas, quando Tereza lavou a louça, Alberto reparou que ela cantarolava baixinho, coisa que não fazia havia anos.","No sábado, saíram sem destino. Pegaram o ônibus errado de propósito e desceram numa praça que nenhum dos dois conhecia. Tomaram café em pé, dividiram um pastel e discordaram sobre qual banco tinha a melhor sombra. Sentaram no que Tereza escolheu, claro."]},{"heading":"O que a lista guardava","paragraphs":["Em algum momento da tarde, Alberto confessou que sentia falta dela, mesmo morando na mesma casa. Não de presença, explicou, mas de atenção. \"A gente anda tão ocupado em dar conta das coisas que esqueceu de dar conta um do outro\", disse, meio sem jeito.","Tereza demorou a responder. Quando falou, foi só: \"Por isso escrevi na lista. Dizer em voz alta me dava vergonha.\"","Riram, os dois, de um jeito que não riam havia muito. Não prometeram mudar de vida nem inventar rituais. Combinaram apenas que, toda sexta, haveria uma linha a mais na lista: um convite pequeno, sem cobrança, que o outro podia aceitar ou propor trocar por outro dia."]},{"heading":"A sexta seguinte","paragraphs":["Na sexta seguinte, Alberto voltou da padaria e encontrou a lista de novo na geladeira. Arroz, café, sabão, banana. E, no fim, em letra miúda: \"Ouvir aquele disco antigo.\"","Pegou a caneta no barbante. Hesitou um segundo, sorrindo. Depois escreveu, embaixo: \"E dançar na cozinha, se ninguém estiver olhando.\"","Do outro lado da casa, Tereza ouviu o riso baixo dele e sorriu também, sem precisar perguntar o motivo."]}]', 'CONTO FICTÍCIO', 'Esta história é uma obra de ficção. Personagens e acontecimentos foram criados para esta publicação.', 'draft', '2026-10-03T12:50:02.475Z');
INSERT OR IGNORE INTO blog_posts (slug, language, title, seo_title, excerpt, category, series, image, image_alt, published, published_iso, read_time, intro, sections, content_notice_label, content_notice_text, status, created_at) VALUES ('conselho-da-semana-peca-o-que-voce-precisa', 'pt-BR', 'Conselho da semana: peça o que você precisa antes de esperar que adivinhem', 'Como pedir o que você precisa ao seu par', 'Uma prática curta para trocar a expectativa silenciosa por um pedido claro e gentil, sem cobrança nem drama.', 'CONSELHO DA SEMANA', 'CONSELHO DA SEMANA', '', 'Casal adulto conversando com calma à mesa da cozinha', '6 de outubro de 2026', '2026-10-06', '4 min de leitura', '["Muita mágoa nasce de um pedido que nunca foi feito. Esperamos que a pessoa que amamos perceba o cansaço, a vontade de um abraço ou a necessidade de ajuda, e ficamos chateados quando ela não percebe.","O conselho desta terça-feira é pequeno e corajoso: escolham uma coisa de que precisam esta semana e peçam em voz alta, em vez de esperar que o outro adivinhe."]', '[{"heading":"Por que pedir é mais difícil do que parece","paragraphs":["Pedir exige se mostrar vulnerável. Dizer \"preciso de ajuda\" ou \"queria mais atenção\" pode soar como exagero, cobrança ou fraqueza. Por isso muita gente prefere insinuar, suspirar ou esperar.","O problema é que o silêncio raramente é lido como pedido. Quem convive conosco também está cansado, distraído e cuidando das próprias preocupações. Um pedido claro é um presente: poupa o outro de tentar adivinhar."]},{"heading":"Como fazer, em quatro passos","items":["Escolha uma única necessidade pequena e concreta, como ajuda com o jantar, vinte minutos de conversa ou um abraço mais demorado.","Comece falando do que você sente, não do que o outro deixou de fazer: \"hoje o dia pesou e ajudaria muito dividir o jantar comigo\", em vez de \"você nunca ajuda\".","Diga exatamente o que ajudaria, num horário e de um jeito possíveis.","Deixe espaço para o outro responder, inclusive para propor uma alternativa."]},{"heading":"Uma frase para começar","paragraphs":["Se não souberem como abrir a conversa, experimentem: \"tem uma coisa pequena que me ajudaria esta semana. Posso te contar?\". A pergunta prepara o terreno e mostra que o pedido não é cobrança.","Pedir não garante ouvir sempre um sim. Mas transforma um incômodo escondido numa conversa possível."]},{"heading":"O pequeno compromisso da semana","paragraphs":["Cada um faz um pedido pequeno até domingo e, se possível, agradece quando for atendido. Se o pedido não puder ser atendido do jeito pedido, vale conversar sobre um jeito que funcione para os dois.","Casais fortes não são os que nunca precisam de nada, e sim os que aprendem a dizer do que precisam sem medo."]}]', NULL, NULL, 'draft', '2026-10-03T12:50:02.475Z');
INSERT OR IGNORE INTO blog_posts (slug, language, title, seo_title, excerpt, category, series, image, image_alt, published, published_iso, read_time, intro, sections, content_notice_label, content_notice_text, status, created_at) VALUES ('tarde-de-domingo-a-dois-10-ideias', 'pt-BR', 'Tarde de domingo a dois: 10 ideias simples para fechar a semana juntos', '10 ideias de tarde de domingo para casais', 'Dez ideias simples e baratas para transformar a tarde de domingo num encontro de verdade, sem pressão e sem estourar o orçamento.', 'IDEIAS PARA CASAIS', 'IDEIAS E GUIAS', '', 'Casal adulto compartilhando um lanche no sofá numa tarde de domingo', '8 de outubro de 2026', '2026-10-08', '6 min de leitura', '["O domingo à tarde costuma ficar no meio do caminho: já não é fim de semana livre, mas ainda não é segunda-feira. Muitos casais passam essas horas cada um no seu celular, adiando as tarefas.","Com um pouco de intenção, esse tempo pode virar o encontro mais fácil da semana. Aqui vão dez ideias para escolher, misturar ou adaptar ao que vocês têm em casa."]', '[{"heading":"Para ficar em casa","items":["Preparem juntos um lanche da tarde diferente: panquecas, uma salada de frutas ou torradas com o que tiver na geladeira.","Montem uma playlist a quatro mãos. Cada um escolhe cinco músicas que marcaram a vida e conta por quê.","Olhem fotos antigas do celular ou de um álbum e escolham a favorita de cada um.","Arrumem juntos um cantinho da casa, como uma gaveta ou uma estante, ouvindo música. Terminar algo a dois dá uma satisfação inesperada."]},{"heading":"Para sair sem gastar","items":["Caminhem sem destino com uma regra simples: a cada esquina, um escolhe o lado.","Levem uma garrafa de café ou chá e sentem num banco de praça ou jardim para observar quem passa.","Entrem numa feira, mercado ou loja do bairro onde nunca estiveram e escolham um item pequeno para experimentar juntos."]},{"heading":"Para cuidar do que vem pela frente","items":["Planejem a semana a dois em quinze minutos: cada um diz uma coisa que espera e uma que o preocupa.","Escrevam três coisas boas que aconteceram na semana e leiam um para o outro.","Escolham o próximo encontro: definam data e uma ideia, mesmo pequena, e marquem no calendário."]},{"heading":"Para não virar obrigação","paragraphs":["Escolham uma ou duas ideias, não as dez. O objetivo é presença, não produtividade.","Se um dos dois estiver cansado, reduzam o plano para trinta minutos. Um encontro curto e verdadeiro vale mais do que um longo e forçado."]}]', NULL, NULL, 'draft', '2026-10-03T12:50:02.475Z');
